int runTalBatch548(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;try{auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};auto root=LibraryStore::root().getChildFile("bulk-tal-fixtures"),folder=root.getChildFile("Export/Presets/Drums");root.createDirectory();LibraryStore::addLibraryRoot(root);juce::Array<juce::File> sources;juce::StringArray originalHashes,configs;
 for(int i=0;i<2;++i){auto file=root.getChildFile(juce::String(i)+"/Loop Name.wav");file.getParentDirectory().createDirectory();juce::AudioBuffer<float> buffer(1,32000);for(int n=0;n<32000;++n)buffer.setSample(0,n,.2f*std::sin(n*.07));require(writeRenderedAudio(file,buffer,8000),"fixture write");Processor p(false);p.autoSave=false;require(p.installAudio(p.readAudio(file),false,0,false),"fixture load");p.setPlaybackMode(0);p.split(4,false);p.sourceBpm=125;p.trimStart=i?8000:0;p.trimEnd=i?24000:8000;p.startMarker=p.trimStart;auto config=p.configurationXml();require(LibraryStore::saveLoop(file,config->toString(),p.audio->contentHash),"save fixture settings");sources.add(file);originalHashes.add(LibraryStore::fingerprint(file));configs.add(LibraryStore::savedLoop(file)->toString());}
 auto midi=root.getChildFile("Skip.mid"),bad=root.getChildFile("Broken.wav");midi.replaceWithText("not needed");bad.replaceWithText("not audio");sources.add(midi);sources.add(bad);int progress=0;auto batch=TalBatch548::run(sources,folder,{},[&](juce::String){++progress;});require(batch.exported==2&&batch.skipped==1&&batch.failed==1&&progress==4,"batch successes, skip and continued failure");require(batch.presets[0]!=batch.presets[1]&&batch.presets[0].getFileName().startsWith("125bpm Loop Name"),"readable BPM prefix and unique preset names");
 juce::AudioFormatManager formats;formats.registerBasicFormats();for(int i=0;i<2;++i){auto xml=juce::XmlDocument::parse(batch.presets[i]);require(xml!=nullptr,"native TAL preset");auto* program=xml->getChildByName("programs")->getChildByName("program");auto* maps=program->getChildByName("samplelayer0")->getChildByName("multisamples");require(maps->getNumChildElements()==(i?2:1)&&program->getIntAttribute("oneshot",1)==0,"per-file slice regions and note-off response");auto* first=maps->getChildElement(0);auto sample=batch.presets[i].getParentDirectory().getChildFile(first->getStringAttribute("url"));require(sample.getFileName()=="Loop Name.wav"&&sample.isAChildOf(root.getChildFile("Export/Samples")),"readable sample repository");std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(sample));require(reader&&reader->lengthInSamples==(i?16000:8000),"each file's saved loop duration");require(originalHashes[i]==LibraryStore::fingerprint(sources[i])&&configs[i]==LibraryStore::savedLoop(sources[i])->toString(),"source audio and settings unchanged");}
 auto before=batch.presets[0].loadFileAsString();auto again=TalBatch548::run({sources[0]},folder);require(again.exported==1&&again.presets[0]!=batch.presets[0]&&batch.presets[0].loadFileAsString()==before,"existing exports never overwritten");
 Processor active(false);active.autoSave=false;active.installAudio(active.readAudio(sources[0]),false,0,false);active.setPlaybackMode(0);active.split(2,false);auto data=active.audio;auto generation=active.loadGeneration.load();TalBatch548::Snapshot snapshot{sources[0],active.audio,active.slices,4000,12000,0,130};auto current=TalBatch548::run({sources[0]},folder,snapshot);require(current.exported==1&&current.presets[0].getFileName().startsWith("130bpm")&&active.audio==data&&active.loadGeneration==generation,"active unsaved snapshot without loading into live engine");
 std::cout<<"Bulk TAL: independent saved regions/slices, active snapshot, BPM names, readable separate WAVs, collisions, unsupported skip, failure continuation and untouched source audio/settings passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<"Bulk TAL: "<<error.what()<<"\n";return 2481;}}
